    encrypted_payload = get_encrypted_payload()
    key_material = extract_key_from_decryptor()  // Bound to this instance

    // Execute decryptor on self
    decrypted_code = decrypt(encrypted_payload, key_material)

    // Transfer control to decrypted payload
