package com.example.todo.reminder

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import androidx.room.Room
import com.example.todo.data.TaskDatabase
import com.example.todo.repository.TaskRepository
import kotlinx.coroutines.runBlocking

class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action == Intent.ACTION_BOOT_COMPLETED) {
            runBlocking {
                val db = Room.databaseBuilder(
                    context.applicationContext,
                    TaskDatabase::class.java,
                    "todo_db"
                ).fallbackToDestructiveMigration().build()
                val repository = TaskRepository(db.taskDao())
                val now = System.currentTimeMillis()
                repository.getAllTasksOnce()
                    .filter { it.reminderTime != null && it.reminderTime > now }
                    .forEach {
                        ReminderScheduler.schedule(context, it.id, it.title, it.reminderTime!!)
                    }
            }
        }
    }
}
