package com.example.todo.viewmodel

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.example.todo.data.Task
import com.example.todo.reminder.ReminderScheduler
import com.example.todo.repository.TaskRepository
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.launch

class TaskViewModel(
    application: Application,
    private val repository: TaskRepository
) : AndroidViewModel(application) {

    val allTasks: Flow<List<Task>> = repository.allTasks

    fun saveTask(task: Task) {
        viewModelScope.launch {
            val newId = repository.insert(task)
            val taskId = if (task.id == 0) newId.toInt() else task.id
            val ctx = getApplication<Application>().applicationContext

            if (task.reminderTime != null && task.reminderTime > System.currentTimeMillis()) {
                ReminderScheduler.schedule(ctx, taskId, task.title, task.reminderTime)
            } else {
                ReminderScheduler.cancel(ctx, taskId)
            }
        }
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            repository.delete(task)
            ReminderScheduler.cancel(getApplication<Application>().applicationContext, task.id)
        }
    }
}

class TaskViewModelFactory(
    private val application: Application,
    private val repository: TaskRepository
) : ViewModelProvider.Factory {
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        if (modelClass.isAssignableFrom(TaskViewModel::class.java)) {
            @Suppress("UNCHECKED_CAST")
            return TaskViewModel(application, repository) as T
        }
        throw IllegalArgumentException("Unknown ViewModel class")
    }
}
