                hasSecond = hasFirst;
                first = num;
                hasFirst = true;
            } else if (hasFirst && num < first && (!hasSecond || num > second)) {
                second = num;
                hasSecond = true;
            }
        }

        return hasSecond ? second : Integer.MIN_VALUE;
    }
}
```

